fn dotnet_version(version: &str) -> String {
    let segments = version.split('-').collect::<Vec<_>>();
    if segments.len() == 3 && segments.iter().all(|part| part.parse::<u64>().is_ok()) {
        return segments.join(".");
    }
    if version.split('.').count() == 3 && version.split('.').all(|part| part.parse::<u64>().is_ok())
    {
        return version.into();
    }
    "0.1.0".into()
}

fn xml_escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn prepare_api(api: &Api) -> Api {
    native_names::prepare(
        api,
        pascal_case,
        pascal_case,
        &[
            "Value",
            "String",
            "Boolean",
            "Int32",
            "Int64",
            "Double",
            "Decimal",
            "Byte",
            "Object",
            "Task",
            "ValueTask",
            "Type",
            "Exception",
            "System",
            "Math",
            "Guid",
            "Uri",
            "List",
            "Dictionary",
            "DateTime",
            "DateOnly",
            "DateTimeOffset",
            "HttpStatusCode",
            "Encoding",
            "HttpClient",
            "HttpRequestMessage",
            "HttpResponseMessage",
            "HttpMethod",
            "HttpContent",
            "JsonElement",
            "JsonDocument",
            "JsonSerializer",
            "JsonSerializerOptions",
            "JsonConverter",
            "JsonConverterFactory",
            "Utf8JsonReader",
            "Utf8JsonWriter",
            "KajiClient",
            "KajiClientOptions",
            "KajiCallOptions",
            "ApiException",
            "Presence",
            "OrderedMultipart",
            "OrderedMultipartPart",
            "MultipartFile",
        ],
    )
}

fn parameter_name(parameter: &OperationParameter) -> String {
    camel_case(
        parameter
            .annotations
            .get("kaji.native_argument")
            .and_then(serde_json::Value::as_str)
            .unwrap_or(&parameter.name),
    )
}

